use xiom.io;
module time_utils {
  pub fn is_leap_year(year: Int) -> Bool {
    if year % 400 == 0 { return true; };
    if year % 100 == 0 { return false; };
    year % 4 == 0
  }

  pub fn days_in_month(month: Int, year: Int) -> Int {
    if month == 2 {
      if is_leap_year(year) { return 29; };
      return 28;
    };
    if month == 4 || month == 6 || month == 9 || month == 11 {
      return 30;
    };
    31
  }

  pub fn convert_to_seconds(hours: Int, minutes: Int, seconds: Int) -> Int {
    hours * 3600 + minutes * 60 + seconds
  }
}

fn main() -> Int {
  io.println(time_utils.is_leap_year(2024).to_str());
  io.println(time_utils.days_in_month(2, 2024).to_str());
  io.println(time_utils.days_in_month(2, 2025).to_str());
  io.println(time_utils.convert_to_seconds(1, 30, 45).to_str());
  return 0;
}
